import React, { useState, useEffect, useRef } from 'react';
import Aura from '../components/Aura';

const GOLD = '#C8A96E';
const s = { label: { fontFamily: 'DM Mono, monospace', fontSize: 9, letterSpacing: '0.22em', textTransform: 'uppercase', color: 'rgba(237,233,224,0.3)' } };

const PHASES = [
  { name: 'Andas in', seconds: 4, label: 'Djupt in genom näsan' },
  { name: 'Håll',     seconds: 7, label: 'Håll andan stilla' },
  { name: 'Andas ut', seconds: 8, label: 'Sakta ut genom munnen' },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(() => {
      c--; setCount(c);
      if (c <= 0) { clearInterval(timer.current); const np = (pi + 1) % 3; setTimeout(() => runPhase(np, np === 0 ? ci + 1 : ci), 400); }
    }, 1000);
  };
  const start = () => { setRunning(true); setDone(false); runPhase(0, 0); };
  useEffect(() => () => clearInterval(timer.current), []);

  const cur = PHASES[phase];
  const scale = running ? (phase === 0 || phase === 1 ? 1.42 : 0.68) : 1.0;
  const dur = running ? (phase === 0 ? `${PHASES[0].seconds}s` : phase === 1 ? '0.5s' : `${PHASES[2].seconds}s`) : '1.2s';
  const easing = phase === 1 ? 'ease' : 'linear';

  if (done) return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={['#0F3A22', '#1A5A32']} intensity={0.6} />
      <div style={{ position: 'absolute', inset: 0, zIndex: 10, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '0 32px' }}>
        <p style={{ ...s.label, marginBottom: 16, color: 'rgba(200,169,110,0.6)' }}>{TOTAL} omgångar · klart</p>
        <h2 style={{ fontSize: 'clamp(34px,9vw,52px)', fontWeight: 800, letterSpacing: '-0.05em', color: '#ede9e0', marginBottom: 10 }}>Bra jobbat</h2>
        <p style={{ fontSize: 14, color: 'rgba(237,233,224,0.4)', marginBottom: 40, fontWeight: 400, maxWidth: 220, lineHeight: 1.7 }}>Ditt nervsystem har lugnat ner sig.</p>
        <div style={{ display: 'flex', gap: 10 }}>
          <button onClick={() => setPage('checkin')} style={{ padding: '13px 24px', borderRadius: 100, background: '#ede9e0', color: '#080808', fontSize: 13, fontWeight: 700, border: 'none' }}>Check-in →</button>
          <button onClick={() => { setDone(false); setRunning(false); }} style={{ padding: '13px 24px', borderRadius: 100, background: 'rgba(255,255,255,0.07)', border: '0.5px solid rgba(255,255,255,0.12)', color: 'rgba(237,233,224,0.55)', fontSize: 13 }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={running ? ['#0A2A4A', '#10224A'] : ['#1A1A3A', '#0A0A2A']} intensity={running ? 0.55 : 0.35} />

      <div style={{ position: 'absolute', inset: 0, zIndex: 10, display: 'flex', flexDirection: 'column', padding: '36px 22px', paddingBottom: 100 }}>

        {/* Phase labels */}
        <div style={{ textAlign: 'center', marginBottom: 'auto' }}>
          <p style={{ ...s.label, marginBottom: 20, letterSpacing: '0.3em' }}>4 – 7 – 8</p>
          <div style={{ display: 'flex', gap: 32, justifyContent: 'center' }}>
            {PHASES.map((p, i) => (
              <div key={i}>
                <div style={{ fontFamily: 'Syne, sans-serif', fontSize: 24, fontWeight: 800, letterSpacing: '-0.04em', lineHeight: 1, color: running && phase === i ? '#ede9e0' : 'rgba(237,233,224,0.15)', transition: 'color 0.6s' }}>{p.seconds}</div>
                <div style={{ fontFamily: 'DM Mono, monospace', fontSize: 8, textTransform: 'uppercase', letterSpacing: '0.1em', color: running && phase === i ? GOLD : 'rgba(237,233,224,0.12)', marginTop: 4, transition: 'color 0.6s' }}>{p.name}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Circle */}
        <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            {/* Outer glow */}
            <div style={{ position: 'absolute', width: 200, height: 200, borderRadius: '50%', background: running ? 'rgba(200,169,110,0.06)' : 'rgba(200,200,220,0.04)', transform: `scale(${scale * 1.6})`, transition: `transform ${dur} ${easing}`, filter: 'blur(20px)' }} />
            {/* Ring */}
            <div style={{ position: 'absolute', width: 200, height: 200, borderRadius: '50%', border: `0.5px solid ${running ? 'rgba(200,169,110,0.3)' : 'rgba(237,233,224,0.1)'}`, transform: `scale(${scale})`, transition: `transform ${dur} ${easing}`, boxSizing: 'border-box' }} />
            {/* Main */}
            <div style={{
              width: 200, height: 200, borderRadius: '50%',
              transform: `scale(${scale})`,
              transition: `transform ${dur} ${easing}, background 1s ease, box-shadow 1s ease`,
              background: running
                ? `radial-gradient(circle at 38% 36%, rgba(200,169,110,0.5) 0%, rgba(150,120,70,0.35) 45%, rgba(80,60,20,0.2) 100%)`
                : 'radial-gradient(circle at 38% 36%, rgba(180,178,210,0.25) 0%, rgba(130,128,170,0.15) 50%, rgba(80,78,120,0.08) 100%)',
              boxShadow: running ? '0 0 80px rgba(200,169,110,0.15), 0 0 160px rgba(200,169,110,0.06)' : 'none',
              position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column',
            }}>
              {running && (
                <>
                  <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 9, letterSpacing: '0.14em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.4)', marginBottom: 4 }}>{cur.name}</span>
                  <span style={{ fontFamily: 'Syne, sans-serif', fontSize: 54, fontWeight: 800, color: 'rgba(255,255,255,0.88)', lineHeight: 1, letterSpacing: '-0.04em' }}>{count}</span>
                  <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 8, color: 'rgba(255,255,255,0.28)', marginTop: 5 }}>{cycle + 1}/{TOTAL}</span>
                </>
              )}
            </div>
          </div>
        </div>

        {/* Bottom */}
        <div>
          {running ? (
            <div style={{ background: 'rgba(8,8,8,0.7)', backdropFilter: 'blur(20px)', borderRadius: 18, padding: '12px 18px', textAlign: 'center', border: '0.5px solid rgba(255,255,255,0.06)' }}>
              <p style={{ ...s.label, color: 'rgba(200,169,110,0.5)' }}>{cur.label}</p>
            </div>
          ) : (
            <>
              <h1 style={{ fontFamily: 'Syne, sans-serif', fontSize: 'clamp(28px,8vw,42px)', fontWeight: 800, letterSpacing: '-0.04em', color: '#ede9e0', marginBottom: 8, lineHeight: 1 }}>Andningsövning</h1>
              <p style={{ fontSize: 13, color: 'rgba(237,233,224,0.38)', fontWeight: 400, lineHeight: 1.75, marginBottom: 20 }}>
                Aktiverar det parasympatiska nervsystemet. 4 cykler.
              </p>
              <button onClick={start} style={{ width: '100%', padding: '15px', borderRadius: 100, background: GOLD, color: '#080808', fontSize: 14, fontWeight: 700, border: 'none', boxShadow: '0 8px 40px rgba(0,0,0,0.5)', fontFamily: 'Syne, sans-serif' }}>
                Starta →
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
